const PAYLOAD =
  ''

const BADGE_SVG =
  'data:image/svg+xml;base64,'

const AWARD_PNG =
  'data:image/png;base64,'

interface EasterEggData {
  email: {
    body: string
    subject: string
    to: string
  }
  quips: string[]
}

let cachedData: EasterEggData | null = null

export function getEasterEggAwardPng(): string {
  return AWARD_PNG
}

export function getEasterEggBadgeSvg(): string {
  return BADGE_SVG
}

export function getEasterEggEmail(): { body: string; subject: string; to: string } {
  return decodePayload().email
}

export function getEasterEggQuips(): string[] {
  return decodePayload().quips
}

function decodePayload(): EasterEggData {
  if (cachedData) return cachedData
  try {
    const binary = atob(PAYLOAD)
    const bytes = Uint8Array.from(binary, (m) => m.charCodeAt(0))
    const json = new TextDecoder().decode(bytes)
    cachedData = JSON.parse(json) as EasterEggData
    return cachedData
  } catch {
    return {
      email: {
        body: '',
        subject: '',
        to: 'hi@psiderman.com',
      },
      quips: ['go web'],
    }
  }
}
